def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_me, last_opp = history[-1]
    coop = sum(1 for a, b in history if b == 'C')
    defco = n - coop
    if defco == 0:
        if last_me == 'D':
            return 'D'
        if n >= 20:
            return 'D'
        return 'C'
    if coop == 0:
        return 'D'
    recent = history[-10:] if n >= 10 else history
    rcoop = sum(1 for a, b in recent if b == 'C')
    rdef = len(recent) - rcoop
    if n >= 20:
        if rcoop >= 9:
            if last_me == 'D' and last_opp == 'C':
                return 'D'
            return 'C'
        if rdef >= 7:
            return 'D'
    dd_streak = 0
    for i in range(1, n + 1):
        m, o = history[-i]
        if m == 'D' and o == 'D':
            dd_streak += 1
        else:
            break
    if dd_streak >= 3:
        if n >= 2 and history[-1][0] == 'C' and history[-2][0] == 'C':
            return 'D'
        return 'C'
    if n >= 2 and history[-1][0] == 'C' and history[-2][0] == 'D' and history[-2][1] == 'D':
        return 'C'
    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        if defco <= max(1, n // 10):
            return 'C'
        if last_me == 'D':
            return 'C'
        return 'D'
    else:
        if n >= 6:
            last6 = history[-6:]
            dcount = sum(1 for a, b in last6 if b == 'D')
            if dcount >= 3:
                return 'D'
        if last_me == 'D':
            my_d_opp_c = sum(1 for a, b in history if a == 'D' and b == 'C')
            if my_d_opp_c >= 2:
                return 'D'
            return 'C'
        return 'C'
